INSERT INTO `CONTENT` (content_id, title, description, release_date, duration) VALUES
(1, 'Hành Trình Bất Tử', 'Hành Trình Bất Tử là phim lẻ thể loại hành động, xoay quanh một vụ án chưa có lời giải.', '2021-12-23', 6524),
(2, 'Cánh Cổng Vĩnh Cửu', 'Cánh Cổng Vĩnh Cửu là phim lẻ thể loại hài, xoay quanh cuộc chiến giành lại quê hương.', '2023-11-20', 7785),
(3, 'Hoàng Hôn Bị Lãng Quên', 'Hoàng Hôn Bị Lãng Quên là phim lẻ thể loại tâm lý, xoay quanh cuộc chiến giành lại quê hương.', '2016-05-07', 7297),
(4, 'Lời Hứa Hà Nội', 'Lời Hứa Hà Nội là phim lẻ thể loại kinh dị, xoay quanh cuộc chiến giành lại quê hương.', '2026-04-28', 8125),
(5, 'Ký Ức Của Gió', 'Ký Ức Của Gió là phim lẻ thể loại tâm lý, xoay quanh cuộc chiến giành lại quê hương.', '2025-03-31', 8499),
(6, 'Mật Mã Cuối Cùng', 'Mật Mã Cuối Cùng là phim lẻ thể loại tâm lý, xoay quanh tình bạn thử thách qua biến cố lớn.', '2019-11-04', 6490),
(7, 'Biển Xanh Rực Lửa', 'Biển Xanh Rực Lửa là phim lẻ thể loại viễn tưởng, xoay quanh lựa chọn khó khăn giữa tình thân và công lý.', '2024-11-29', 8739),
(8, 'Bóng Đêm Im Lặng', 'Bóng Đêm Im Lặng là phim lẻ thể loại tài liệu, xoay quanh lựa chọn khó khăn giữa tình thân và công lý.', '2025-02-16', 8861),
(9, 'Con Đường Tuổi Trẻ', 'Con Đường Tuổi Trẻ là phim lẻ thể loại phiêu lưu, xoay quanh một vụ án chưa có lời giải.', '2018-05-08', 8807),
(10, 'Hành Trình Tuổi Trẻ', 'Hành Trình Tuổi Trẻ là phim lẻ thể loại hài, xoay quanh cuộc truy đuổi nghẹt thở xuyên thành phố.', '2024-06-30', 8498),
(11, 'Đảo Hoang Hà Nội', 'Đảo Hoang Hà Nội là phim lẻ thể loại tâm lý, xoay quanh hành trình tìm lại chính mình.', '2026-10-06', 8304),
(12, 'Đảo Hoang Phía Bắc', 'Đảo Hoang Phía Bắc là phim lẻ thể loại phiêu lưu, xoay quanh mối tình vượt qua khoảng cách địa lý.', '2018-09-21', 5651),
(13, 'Con Đường Trong Sương', 'Con Đường Trong Sương là phim lẻ thể loại hình sự, xoay quanh hành trình tìm lại chính mình.', '2017-11-08', 5754),
(14, 'Cánh Cổng Của Gió', 'Cánh Cổng Của Gió là phim lẻ thể loại hoạt hình, xoay quanh cuộc truy đuổi nghẹt thở xuyên thành phố.', '2026-10-11', 9162),
(15, 'Giấc Mơ Của Mẹ', 'Giấc Mơ Của Mẹ là phim lẻ thể loại hoạt hình, xoay quanh mối tình vượt qua khoảng cách địa lý.', '2016-01-14', 7108),
(16, 'Biển Xanh Sài Gòn', 'Biển Xanh Sài Gòn là phim lẻ thể loại hình sự, xoay quanh nhóm bạn trẻ khởi nghiệp giữa thời khó.', '2017-05-30', 9204),
(17, 'Giấc Mơ Vĩnh Cửu', 'Giấc Mơ Vĩnh Cửu là phim lẻ thể loại phiêu lưu, xoay quanh một bí mật gia đình được giấu kín suốt nhiều năm.', '2026-10-12', 8897),
(18, 'Giấc Mơ Lạc Lối', 'Giấc Mơ Lạc Lối là phim lẻ thể loại viễn tưởng, xoay quanh nhóm bạn trẻ khởi nghiệp giữa thời khó.', '2017-01-16', 7567),
