-- FILE: 05_sample_data.sql  |  Dữ liệu mẫu cho mini_netflix (11 bảng)
-- Chạy SAU khi đã tạo bảng, view, hàm, trigger. Thứ tự 01 -> 11 đã đúng.
-- =========================================================================
USE mini_netflix;
SET NAMES utf8mb4;

-- 01_SUBSCRIPTION_PLAN: 3 dòng

-- 02_USER: 300 dòng

-- 03_PROFILE: 379 dòng

-- 04_CONTENT: 1230 dòng

-- 05_MOVIE: 300 dòng

-- 06_TV_SERIES: 40 dòng

-- 07_SEASON: 100 dòng

-- 08_EPISODE: 930 dòng

-- 09_GENRE: 2395 dòng

-- 10_WATCH_LIST: 1914 dòng

-- 11_WATCH_HISTORY: 3292 dòng

-- Kiểm tra nhanh số dòng
SELECT 'SUBSCRIPTION_PLAN' t, COUNT(*) n FROM SUBSCRIPTION_PLAN UNION ALL SELECT 'USER', COUNT(*) FROM `USER` UNION ALL SELECT 'PROFILE', COUNT(*) FROM PROFILE UNION ALL SELECT 'CONTENT', COUNT(*) FROM CONTENT UNION ALL SELECT 'MOVIE', COUNT(*) FROM MOVIE UNION ALL SELECT 'TV_SERIES', COUNT(*) FROM TV_SERIES UNION ALL SELECT 'SEASON', COUNT(*) FROM SEASON UNION ALL SELECT 'EPISODE', COUNT(*) FROM EPISODE UNION ALL SELECT 'GENRE', COUNT(*) FROM GENRE UNION ALL SELECT 'WATCH_LIST', COUNT(*) FROM WATCH_LIST UNION ALL SELECT 'WATCH_HISTORY', COUNT(*) FROM WATCH_HISTORY;
